WITH with_windows AS (SELECT id, starts_on, discount_pct, STDDEV_SAMP(discount_pct) OVER (PARTITION BY channel) AS channel_stddev_samp_discount_pct, RANK() OVER (PARTITION BY DATE_TRUNC('MONTH', starts_on), channel ORDER BY discount_pct DESC) AS discount_pct_rank, ROW_NUMBER() OVER (PARTITION BY YEAR(ends_on), promo_code ORDER BY ends_on, id) AS row_seq, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY starts_on, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS discount_pct_avg_3, LAG(discount_pct, 2) OVER (PARTITION BY channel ORDER BY starts_on, id) AS prev_discount_pct FROM promotions) SELECT id, row_seq FROM with_windows;
